+package com.vlad.simion.data.network

+import com.vlad.simion.data.model.response.GithubRepositoryDetailsDto
+import com.vlad.simion.data.model.response.GithubRepositoryDto
+import com.vlad.simion.domain.common.DataSourceType
+import com.vlad.simion.domain.common.PreferenceManager
+import retrofit2.Response
+import javax.inject.Inject
+import javax.inject.Named
+
+/**
+ * Dynamic API wrapper that selects between mock and remote API at call time
+ * without blocking the main thread during initialization
+ */
+class DynamicGithubApi @Inject constructor(
+ @Named("mockApi") private val mockApi: GithubApi,
+ @Named("remoteApi") private val remoteApi: GithubApi,
+ private val preferenceManager: PreferenceManager
+) : GithubApi {
+
+ override suspend fun getRepositories(): Response<List<GithubRepositoryDto>> {
+ val api = selectApi()
+ return api.getRepositories()
+ }
+
+ override suspend fun getRepositoryDetails(path: String): Response<GithubRepositoryDetailsDto> {
+ val api = selectApi()
+ return api.getRepositoryDetails(path)
+ }
+
+ private suspend fun selectApi(): GithubApi {
+ val dataSourceType = preferenceManager.getDataSourceType()
+ return if (dataSourceType == DataSourceType.MOCK) {
+ mockApi
+ } else {
+ remoteApi
+ }
+ }
+}
+
