class PreferencesManagerImpl @Inject constructor(
 @ApplicationContext private val context: Context,
) : PreferenceManager {
 private val sharedPreferences: SharedPreferences by lazy {
 context.getSharedPreferences(PREF_NAME, Context.MODE_PRIVATE)
 }

 override fun saveDataSourceType(dataSourceType: DataSourceType) {
 val isMockEnabled = dataSourceType == DataSourceType.MOCK
 sharedPreferences.edit(commit = true) {
 putBoolean(
 KEY_MOCK_ENABLED, isMockEnabled
 )
 }
 }

 override fun getDataSourceType() =
 if (sharedPreferences.getBoolean(KEY_MOCK_ENABLED, false)) {
 DataSourceType.MOCK
 } else {
 DataSourceType.REMOTE
 }

 companion object {
 private const val PREF_NAME = "minderaApp_preferences"
 private const val KEY_MOCK_ENABLED = "is_mock_enabled"
 }
}

