```kotlin
LaunchedEffect(Unit) {
 viewModel.restartEffect.collect {
 val intent = context.packageManager.getLaunchIntentForPackage(context.packageName)
 intent?.addFlags(android.content.Intent.FLAG_ACTIVITY_CLEAR_TOP)
