package com.vlad.simion.minderaassignment.ui.repositories

import android.util.Log
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.vlad.simion.domain.common.DataSourceType
import com.vlad.simion.domain.common.Result
import com.vlad.simion.domain.model.response.GithubRepositoryEntity
import com.vlad.simion.domain.usecase.GetGithubRepositoriesUseCase
import com.vlad.simion.domain.usecase.GetGithubRepositoryDetailsUseCase
import com.vlad.simion.domain.usecase.SetDataSourceTypeUseCase
import com.vlad.simion.minderaassignment.di.DispatcherProvider
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.async
import kotlinx.coroutines.awaitAll
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import javax.inject.Inject

@HiltViewModel
class RepositoriesListViewModel @Inject constructor(
 private val getRepositories: GetGithubRepositoriesUseCase,
 private val getRepositoryDetails: GetGithubRepositoryDetailsUseCase,
 private val setDataSourceType: SetDataSourceTypeUseCase,
 private val dispatcherProvider: DispatcherProvider
) : ViewModel() {

 private val _uiState = MutableStateFlow<RepositoriesUiState>(RepositoriesUiState.Loading)
 val uiState: StateFlow<RepositoriesUiState> = _uiState.asStateFlow()

 private val _restartEffect = MutableSharedFlow<Unit>()
 val restartEffect: SharedFlow<Unit> = _restartEffect.asSharedFlow()

 init {
 loadRepositories()
 }

 fun handleEvents(event: RepositoriesUiEvent) {
 when (event) {
 RepositoriesUiEvent.OnRefresh -> loadRepositories()
 RepositoriesUiEvent.OnSwitchToMockData -> switchToMockData()
 }
 }

 private fun switchToMockData() {
 viewModelScope.launch(dispatcherProvider.io) {
 setDataSourceType(DataSourceType.MOCK)
 _restartEffect.emit(Unit)
 }
 }

 private fun loadRepositories() {
 viewModelScope.launch(dispatcherProvider.io) {
 _uiState.update { RepositoriesUiState.Loading }

 when (val result = getRepositories()) {
 is Result.Success -> {
 _uiState.update { RepositoriesUiState.Success(result.data) }
 fetchRepositoryDetails(result.data)
 }
 is Result.Error -> {
 _uiState.update { RepositoriesUiState.Error(result.message) }
 }
 }
 }
 }

 private fun fetchRepositoryDetails(repositories: List<GithubRepositoryEntity>) {
 viewModelScope.launch(dispatcherProvider.io) {
 val starCountsByFullName = fetchAllStarCounts(repositories)

 if (starCountsByFullName.isNotEmpty()) {
 updateRepositoriesWithStarCounts(starCountsByFullName)
 }
 }
 }

 private suspend fun fetchAllStarCounts(
 repositories: List<GithubRepositoryEntity>
 ): Map<String, Int> {
 val deferredResults = repositories
 .mapNotNull { it.fullName }
 .map { fullName ->
 viewModelScope.async(dispatcherProvider.io) {
 fetchStarCountForRepository(fullName)
 }
 }

 return deferredResults
 .awaitAll()
 .filterNotNull()
 .toMap()
 }

 private suspend fun fetchStarCountForRepository(fullName: String): Pair<String, Int>? {
 return when (val result = getRepositoryDetails(fullName)) {
 is Result.Success -> {
 val starCount = result.data.stargazersCount ?: return null
 fullName to starCount
 }
 is Result.Error -> null
 }
 }

 private fun updateRepositoriesWithStarCounts(starCountsByFullName: Map<String, Int>) {
 _uiState.update { currentState ->
 when (currentState) {
 is RepositoriesUiState.Success -> {
 val updatedRepositories = currentState.repositories.map { repository ->
 updateRepositoryWithStarCount(repository, starCountsByFullName)
 }
 RepositoriesUiState.Success(updatedRepositories)
 }
 else -> currentState
 }
 }
 }

 private fun updateRepositoryWithStarCount(
 repository: GithubRepositoryEntity,
 starCountsByFullName: Map<String, Int>
 ): GithubRepositoryEntity {
 val fullName = repository.fullName ?: return repository
 val starCount = starCountsByFullName[fullName] ?: return repository
 return repository.copy(stargazersCount = starCount)
 }
}

