package com.vlad.simion.minderaassignment.ui.repositories

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.grid.GridCells
import androidx.compose.foundation.lazy.grid.LazyVerticalGrid
import androidx.compose.foundation.lazy.grid.items
import androidx.compose.material3.Button
import androidx.compose.material3.ExperimentalMaterial3Api
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Scaffold
import androidx.compose.material3.Text
import androidx.compose.material3.TopAppBar
import androidx.compose.material3.pulltorefresh.PullToRefreshBox
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import com.vlad.simion.designsystem.widgets.MListItem
import com.vlad.simion.domain.model.response.GithubRepositoryEntity

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RepositoriesScreen(
 onRepositoryClick: (String) -> Unit,
 viewModel: RepositoriesViewModel = hiltViewModel()
) {
 val uiState by viewModel.uiState.collectAsStateWithLifecycle()
 val isRefreshing = uiState is RepositoriesUiState.Loading

 Scaffold(
 topBar = {
 TopAppBar(
 title = { Text("GitHub Repositories") }
 )
 }
 ) { paddingValues ->
 PullToRefreshBox(
 isRefreshing = isRefreshing,
 onRefresh = { viewModel.loadRepositories() },
 modifier = Modifier
 .fillMaxSize()
 .padding(paddingValues)
 ) {
 when (val state = uiState) {
 is RepositoriesUiState.Loading -> {
 }

 is RepositoriesUiState.Success -> {
 if (state.repositories.isEmpty()) {
 Box(
 modifier = Modifier.fillMaxSize(),
 contentAlignment = Alignment.Center
 ) {
 Text(text = "No repositories found")
 }
 } else {
 LazyVerticalGrid(
 columns = GridCells.Fixed(2),
 modifier = Modifier.fillMaxSize(),
 contentPadding = PaddingValues(16.dp),
 horizontalArrangement = Arrangement.spacedBy(8.dp),
 verticalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 items(state.repositories) { repository ->
 MListItem(
 imageUrl = repository.owner?.avatarUrl,
 title = repository.name ?: "Unknown",
 description = repository.description
 ?: "No description available",
 onClick = {
 repository.name?.let { onRepositoryClick(it) }
 },
 imageContentDescription = "Avatar of ${repository.owner?.login}"
 )
 }
 }
 }
 }

 is RepositoriesUiState.Error -> {
 Box(
 modifier = Modifier.fillMaxSize(),
 contentAlignment = Alignment.Center
 ) {
 Column(
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 Text(
 text = "Error: ${state.message}",
 color = MaterialTheme.colorScheme.error
 )
 Spacer(modifier = Modifier.height(16.dp))
 Button(onClick = { viewModel.loadRepositories() }) {
 Text("Retry")
 }
 }
 }
 }
 }
 }
 }
}

