@OptIn(ExperimentalSharedTransitionApi::class)
@Composable
private fun RepositoryInfoCard(
 repository: GithubRepositoryEntity,
 sharedTransitionScope: SharedTransitionScope,
 animatedContentScope: AnimatedVisibilityScope
) {
 with(sharedTransitionScope) {
 ElevatedCard(
 modifier = Modifier.fillMaxWidth(),
 elevation = CardDefaults.elevatedCardElevation(defaultElevation = 4.dp)
 ) {
 Column(
 modifier = Modifier
 .fillMaxWidth()
 .padding(20.dp)
 ) {
 // Repository Header
 Row(
 verticalAlignment = Alignment.CenterVertically,
 modifier = Modifier.fillMaxWidth()
 ) {
 Icon(
 imageVector = Icons.Default.FolderOpen,
 contentDescription = null,
 tint = MaterialTheme.colorScheme.primary,
 modifier = Modifier.size(32.dp)
 )
 Spacer(modifier = Modifier.width(12.dp))
 Column(modifier = Modifier.weight(1f)) {
 Text(
 text = "Repository",
 style = MaterialTheme.typography.labelMedium,
 color = MaterialTheme.colorScheme.onSurfaceVariant
 )
 Spacer(modifier = Modifier.height(4.dp))
 Text(
 text = repository.name ?: "Unknown",
 style = MaterialTheme.typography.headlineSmall,
 color = MaterialTheme.colorScheme.onSurface
 )
 }
 }

 Spacer(modifier = Modifier.height(16.dp))
 HorizontalDivider()
 Spacer(modifier = Modifier.height(16.dp))

 // Full Name
 InfoRow(
 icon = Icons.Default.Label,
 label = "Full Name",
 value = repository.fullName ?: "N/A"
 )

 Spacer(modifier = Modifier.height(12.dp))

 // Description
 if (!repository.description.isNullOrBlank()) {
 val description = repository.description!!
 InfoRow(
 icon = Icons.Default.Description,
 label = "Description",
 value = description,
 maxLines = Int.MAX_VALUE
 )
 Spacer(modifier = Modifier.height(12.dp))
 }

 // Stars
 InfoRow(
 icon = Icons.Default.Star,
 label = "Stars",
 value = repository.stargazersCount?.toString() ?: "0",
 iconTint = MaterialTheme.colorScheme.tertiary
 )

 Spacer(modifier = Modifier.height(12.dp))

 // Repository URL
 InfoRow(
 icon = Icons.Default.Link,
 label = "URL",
 value = repository.htmlUrl ?: "N/A",
 maxLines = 2
 )

 Spacer(modifier = Modifier.height(12.dp))

 // Repository Properties
 Row(
 horizontalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 if (repository.private == true) {
 AssistChip(
 onClick = { },
 label = { Text("Private") },
 leadingIcon = {
 Icon(
 imageVector = Icons.Default.Lock,
 contentDescription = null,
 modifier = Modifier.size(18.dp)
 )
 }
 )
 } else {
 AssistChip(
 onClick = { },
 label = { Text("Public") },
 leadingIcon = {
 Icon(
 imageVector = Icons.Default.LockOpen,
 contentDescription = null,
 modifier = Modifier.size(18.dp)
 )
 }
 )
 }

 if (repository.fork == true) {
 AssistChip(
 onClick = { },
 label = { Text("Fork") },
 leadingIcon = {
 Icon(
 imageVector = Icons.Default.CallSplit,
 contentDescription = null,
 modifier = Modifier.size(18.dp)
 )
 }
 )
 }
 }
 }
 }
 }
}

@Composable
private fun InfoRow(
 icon: androidx.compose.ui.graphics.vector.ImageVector,
 label: String,
 value: String,
 maxLines: Int = 1,
 iconTint: androidx.compose.ui.graphics.Color = MaterialTheme.colorScheme.primary
) {
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 Icon(
 imageVector = icon,
 contentDescription = null,
 tint = iconTint,
 modifier = Modifier.size(24.dp)
 )
 Column(modifier = Modifier.weight(1f)) {
 Text(
 text = label,
 style = MaterialTheme.typography.labelSmall,
 color = MaterialTheme.colorScheme.onSurfaceVariant
 )
 Spacer(modifier = Modifier.height(2.dp))
 Text(
 text = value,
 style = MaterialTheme.typography.bodyMedium,
 color = MaterialTheme.colorScheme.onSurface,
 maxLines = maxLines,
 overflow = TextOverflow.Ellipsis
 )
 }
 }
}

